import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B9qR_F1m.js";const s="/bilder/timing.jpg",c=JSON.parse('{"title":"Timing","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/timing.md","filePath":"bereiche/timing.md"}'),a={name:"bereiche/timing.md"};function l(d,e,o,u,g,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h1><p>In einem Paket muss die SEAD vor dem Strike am Ziel sein, die CAP muss stehen, bevor der Tanker ankommt. Im Bereich Timing hängst du alle Flights an <strong>eine</strong> Bezugszeit – die <strong>H-Hour</strong> – und siehst sofort, ob die Routen dazu passen.</p><p><img src="'+s+'" alt="Sync-Matrix mit H-Hour, DEAD-Fenster, CAP und Tanker, darunter Editor und Wegpunkt-Tabelle" loading="lazy"></p><h2 id="so-funktioniert-es" tabindex="-1">So funktioniert es <a class="header-anchor" href="#so-funktioniert-es" aria-label="Permalink to &quot;So funktioniert es&quot;">​</a></h2><ol class="steps"><li><b>H-Hour setzen</b> – der Bezugspunkt des Pakets, meist der TOT des ersten Strikers. Alle Zeiten hängen an H; verschiebst du H, wandert das ganze Paket mit.</li><li><b>Flights hinzufügen</b> – unter <i>Ohne Timing</i> einen Flight anklicken, oder <b>Alle hinzufügen</b>.</li><li><b>Auftrag wählen</b> – <b>Nur Sollzeiten</b> für Flights, die du nur über Planungspunkte und Sollzeiten führst, <b>TOT</b> mit Fenster für Striker, <b>Vul</b> für CAP, Escort und Tanker, <b>SEAD/DEAD-Fenster</b> für die Weasels (DEAD geht auch als <b>DEAD-TOT</b>, z. B. ein Strike auf eine SAM-Stellung zu einer festen Zeit). Zeiten relativ zu H, z. B. <code>H-10</code> bis <code>H+15</code>.</li><li><b>Push- und Zielpunkt</b> wählen: einen Steerpoint der Route, einen Planungspunkt oder eine Zielangabe aus dem Angriff. Die Matrix vergleicht mit den ETAs der Route und zeigt, wer zu früh oder zu spät ist.</li></ol><h2 id="die-sync-matrix" tabindex="-1">Die Sync-Matrix <a class="header-anchor" href="#die-sync-matrix" aria-label="Permalink to &quot;Die Sync-Matrix&quot;">​</a></h2><p>Oben eine Zeitachse, relativ zu H und als Uhrzeit. Jeder Flight ist eine Zeile, gruppiert nach Rolle:</p><table tabindex="0"><thead><tr><th>Zeichen</th><th>Bedeutung</th></tr></thead><tbody><tr><td>grauer Balken</td><td>Anlassen und Taxi bis Abheben (rückwärts gerechnet)</td></tr><tr><td>farbiger Balken</td><td>TOT-Fenster, Vul oder SEAD-Fenster</td></tr><tr><td>⚑</td><td>Push</td></tr><tr><td>gelbe Raute mit Name</td><td>Zeit an einem <a href="./planung#planungspunkte">Planungspunkt</a>, z. B. <em>MARSHAL ALPHA</em></td></tr><tr><td>graue Raute</td><td>weitere Sollzeit ohne Planungspunkt (Name beim Darüberfahren)</td></tr><tr><td>dünne Linie mit Nummern</td><td>Route mit Steerpoints (aus der Cartridge, sonst aus der Mission)</td></tr><tr><td>●</td><td>Ankunft am Zielpunkt laut Route – rot, wenn außerhalb des Fensters</td></tr><tr><td>gestrichelte Linie</td><td>Abstand zwischen nötigem Start und Start im Mission Editor</td></tr><tr><td>rot schraffiert</td><td>zu nahe an einem anderen Flight</td></tr></tbody></table><p>Senkrechte Linien markieren H, Sonnenauf- und -untergang.</p><p><strong>Bedienen:</strong> Fenster ziehen verschiebt die Zeiten (rastet auf 15 s, mit <kbd>Alt</kbd> auf 1 s). Kommt eine Kante bis auf wenige Pixel an einen Wegpunkt des Flights, an H oder an das Fenster eines anderen Flights, haftet sie dort (dünne blaue Linie); für feinere Arbeit hineinzoomen, <kbd>Alt</kbd> schaltet das Haften ab. H ziehen verschiebt das ganze Paket. Auf freier Fläche einen Bereich ziehen zoomt, Doppelklick zoomt zurück. Rechts oben wechselst du zwischen <strong>Aufträge</strong> (um die Fenster herum) und <strong>Ganze Routen</strong> (vom Start bis zur Landung).</p><h2 id="ein-flight-im-detail" tabindex="-1">Ein Flight im Detail <a class="header-anchor" href="#ein-flight-im-detail" aria-label="Permalink to &quot;Ein Flight im Detail&quot;">​</a></h2><p>Zeile anklicken, darunter erscheint:</p><ul><li><p><strong>Fenster</strong> und <strong>Push</strong> – Zeiten relativ zu H (<code>H-10</code>, <code>H+05:30</code>) oder als Uhrzeit in Ortszeit (<code>07:55</code>); gespeichert wird immer relativ zu H, H verschieben nimmt alles mit.</p></li><li><p><strong>Push-Punkt</strong> und <strong>Ziel-Punkt</strong> – Steerpoints der Route (bei Cartridges auch aus Route 2 und 3), ein <strong>Planungspunkt</strong> (◆) oder beim Ziel eine <strong>Zielangabe</strong> (✛) aus dem Angriffsplaner. Einen Planungspunkt oder eine Zielangabe ordnet der Flight im Reiter Route einem Steerpoint zu; verglichen wird danach mit diesem.</p></li><li><p><strong>Ziel</strong> (optional) – worauf der Flight plant:</p><ul><li>eine <strong>Bodengruppe der Gegenseite</strong> (du siehst als Designer alle): Sie wird eine Zielangabe des Flights im <a href="./angriff">Angriffsplaner</a> und gleich sein Ziel-Punkt. Der Flight sieht nur diese Gruppe, keine anderen.</li><li>ein <strong>Zielgebiet</strong> – ein <a href="./planung#planungspunkte">Planungspunkt</a> <strong>TGT</strong>. Er wird gleich der Ziel-Punkt des Flights, und der Flight sieht ihn auf der Karte.</li><li>eine <strong>AO</strong> – eine Fläche aus der <a href="./planung">Planung</a>, mit Hinweis: eine taktische Grafik (KB, ROZ, NFA, RFA, ▭) oder eine eigene Zeichnung (✎) wie die Vorlage <em>Kill Box</em>, eine Fläche, ein Rechteck, ein Kreis oder ein Oval. Zur Wahl stehen Zeichnungen auf der Ebene der eigenen Seite und auf <em>Common</em>; was auf <em>Author</em> oder der Gegenseite liegt, sieht der Flight in DCS nicht und fehlt deshalb.</li><li><strong>TOO</strong> (Targets of Opportunity) – ohne genaue Angaben, höchstens ein Hinweis wie <em>Fahrzeuge entlang der Straße nach Senaki</em>. Unter <strong>Gebiet</strong> grenzt du es optional auf einen TGT-Punkt oder eine Fläche ein, dieselbe Auswahl wie bei der AO (<em>TOO in KB AB12</em>).</li></ul><p>Das Ziel steht auf der Lineup Card über der Flight-Tabelle; andere Flights sehen es nicht. Wählst du statt einer Bodengruppe etwas anderes, verschwindet ihre Zielangabe wieder.</p></li><li><p><strong>Nur Sollzeiten</strong> – statt TOT, Vul oder SEAD: Der Flight hat nur seine Sollzeiten, ohne Fenster in der Matrix. Wählst du wieder einen Auftrag, kommt der alte zurück.</p></li><li><p><strong>Rückwärts geplant</strong> – <em>Anlassen 07:30 · Taxi 07:45 · Abheben 07:53 · Push 08:10 · Beginn 08:20</em>. Passt der Start im Mission Editor nicht, gibt es einen Hinweis. Bei <strong>Client-Slots</strong> startet der Pilot, wenn er einsteigt – Shardwing rechnet die Route ab diesem Start und warnt nur, wenn der Slot zu spät frei wird. Hat der Flight in seiner Cartridge TOS gesetzt, gelten diese: Der Start richtet sich nach dem ersten TOS, und die Matrix zeigt, wie weit die TOS vom Plan abweichen.</p></li><li><p><strong>Sollzeiten</strong> – die Hauptsache der Planung, in der Reihenfolge, in der der Flight sie abfliegt: Am Griff ⠿ ziehst du sie in eine andere Reihenfolge, genau so stehen sie auch im Reiter Route. Über jeder Sollzeit mit Ort steht der Weg vom Ort davor – Entfernung, Zeit und die nötige Geschwindigkeit über Grund. Über 600 kt (oder wenn die Zeit nicht danach liegt) ist das <strong>zu knapp</strong>: rot hier und als Warnung unter <em>Prüfungen</em>. Jede Sollzeit hat z. B. <em>RV H−25</em> oder <em>IP H−03</em>, wahlweise mit Fenster und <strong>Ort</strong> (Koordinate; Rechtsklick auf die Karte kopiert eine). Mit Ort setzt der Flight seinen Steerpoint beim Zuordnen genau dorthin. Sie hängen an keinem Wegpunkt: Der Flight ordnet sie im Reiter <a href="./flights#route">Route</a> seinen Steerpoints zu. Darunter steht für jede Sollzeit, wo und wann die Route dort ist; Abweichungen erscheinen auch unter <em>Prüfungen</em>. Die Lineup Card zeigt bis zu drei davon in der Zeitleiste. Jede Sollzeit kann eine <strong>Höhe</strong> haben (FL <em>180</em> oder ft <em>8000</em>; ältere Pläne mit Band zeigen die Unterkante) und, wenn sie einen Ort hat, eine <strong>Elevation</strong> (optional, sonst nimmt der Pilot das Gelände). Sollzeiten ohne Ort bleiben möglich. Umgekehrt macht <strong>Nur Ort</strong> aus einer Sollzeit einen Punkt ohne Zeit, dann ist der Ort Pflicht: Er erscheint nur im Reiter Route des Flights und wird im Timing weder gezeigt noch geprüft. Gibt es <a href="./planung#planungspunkte">Planungspunkte</a>, wählst du bei <strong>+ Sollzeit</strong> einen Punkt oder eine freie Sollzeit; jeder Punkt geht je Flight nur einmal; der Flight wird dann dort eingetragen (2 min nach dem letzten Flight am Punkt). Gehört eine Sollzeit zu einem <a href="./planung#planungspunkte">Planungspunkt</a>, sind Name und Ort gesperrt (◆ öffnet den Punkt); eine Sollzeit mit Ort machst du mit <strong>◆ Als Planungspunkt</strong> zu einem.</p></li><li><p><strong>Push und Ziel als feste Sollzeiten</strong> – Push und TOT (bzw. On Station, SEAD-Beginn) stehen als blaue Einträge mit dem Schild <em>Auftrag</em> zwischen den Sollzeiten, nach Zeit einsortiert. Sie sind mit den Feldern oben verknüpft: Zeit und Ort ändern sich hier und dort gemeinsam; löschen lassen sie sich nicht, am Griff ⠿ aber wie jede Sollzeit an eine andere Stelle ziehen – so stehen sie dann auch im Reiter Route. Wählst du als Push- oder Ziel-Punkt einen Planungspunkt, an dem der Flight schon eine Sollzeit hat, wird diese mit dem Auftrag zusammengeführt (ein leerer Push übernimmt ihre Zeit); umgekehrt bietet <strong>+ Sollzeit</strong> diesen Punkt nicht mehr an. Ältere Pläne mit doppelter Zeit zeigen <em>doppelt mit Push/Ziel</em> und <strong>Zusammenführen</strong>.</p></li><li><p><strong>Höhenblock</strong> – z. B. FL200 bis FL220. Flights in getrennten Blöcken werden nicht gegeneinander geprüft.</p></li><li><p><strong>Tanken (AAR)</strong> – Slots beim Tanker buchen, siehe unten.</p></li><li><p><strong>Bemerkung</strong> – Freitext für die Unterlagen.</p></li><li><p><strong>Übertragen auf …</strong> – kopiert Teile dieses Flights einmalig auf andere, in drei Schritten: <strong>Was</strong> – <em>Auftrag, Ziel und Fenster</em> (eine Bodengruppe ohne ihre Zielangabe), <em>Push-Zeit</em>, <em>Höhenblock</em>, <em>AAR-Slots</em>, <em>Notiz</em> und jede <strong>Sollzeit einzeln</strong>. <strong>Auf</strong> – Flights ankreuzen oder <strong>Alle Player-Flights</strong>, <strong>Alle</strong>, <strong>Keine</strong>. <strong>Staffeln</strong> – <em>Zeit je Flight +</em> und <em>Höhe je Flight +</em>: Der erste bekommt +2 min und +2.000 ft, der zweite +4 min und +4.000 ft usw. Danach ist jeder Flight einzeln änderbar; Zeiten an Planungspunkten bleiben mit dem Punkt verbunden.</p></li></ul><h2 id="treffpunkte" tabindex="-1">Treffpunkte <a class="header-anchor" href="#treffpunkte" aria-label="Permalink to &quot;Treffpunkte&quot;">​</a></h2><p>Rechts unten stehen deine <a href="./planung#planungspunkte">Planungspunkte</a> mit allen Flights dort: Zeit, Fenster und Höhe je Flight, dazu <em>Zeiten staffeln</em> und <em>Höhen staffeln</em>. Hier lässt sich alles einstellen, ohne zur Karte zu wechseln; <strong>Karte</strong> öffnet den Punkt unter Planung.</p><p>Die Dauern für <strong>Coldstart</strong>, <strong>Hotstart</strong> und <strong>Taxi</strong> stellst du links unter <em>Rückwärts bis zum Anlassen</em> ein (Standard 15, 2 und 8 Minuten).</p><h2 id="wegpunkte-mit-tos" tabindex="-1">Wegpunkte mit TOS <a class="header-anchor" href="#wegpunkte-mit-tos" aria-label="Permalink to &quot;Wegpunkte mit TOS&quot;">​</a></h2><p>Rechts unten die Route des gewählten Flights mit Höhe, Geschwindigkeit, <strong>TOS</strong> und Zeit relativ zu H; Push- und Zielpunkt sind markiert. Bei der Missionsroute sind Name, Höhe, Speed und TOS hier direkt änderbar – eine Zeit sperrt den Punkt wie ETA-Lock. Kommt die Route aus einer Cartridge, setzt du TOS im <a href="./dtc">DTC</a>. Die Spalte <strong>Soll</strong> zeigt die Sollzeiten an den Steerpoints, denen der Flight sie zugeordnet hat. Hat der Flight Push oder Ziel einem anderen Steerpoint zugeordnet als du, vergleicht die Matrix mit seinem; deine Auswahl bleibt gespeichert.</p><h2 id="tanker" tabindex="-1">Tanker <a class="header-anchor" href="#tanker" aria-label="Permalink to &quot;Tanker&quot;">​</a></h2><p>Tanker aus der Mission (Aufgabe <em>Refueling</em>) bekommen eine eigene Zeile mit Orbit-Fenster. Bei KI-Tankern mit Track ist das Fenster zugleich On und Off Track im <a href="./flights#zeitplan">Auftrag</a>; Off Track beendet dort den Orbit. Empfänger buchen ihren <strong>AAR-Slot</strong> in ihrer eigenen Zeile – vor dem Ziel, danach oder beides. Mit <strong>ohne Zeit</strong> teilst du nur den Tanker zu, ohne Zeitslot; der Flight plant dann selbst, wann er tankt, und <strong>meldet</strong> seine Zeit aus dem <a href="./dtc#tos-rechner">TOS-Rechner</a>. Du siehst sie am Slot (<em>Gemeldet: 08:10L–08:16L</em>) und in der Warteschlange des Tankers; ab dann prüft Shardwing den Slot wie einen mit Zeit. Solange nichts gemeldet ist, steht dort, dass der Flight noch keine Zeit gemeldet hat. Der Slot ist zugleich der Treffpunkt: Der Flight sieht ihn als <em>AR</em> am Beginn des Tracks auf der Karte und im Reiter Route. Shardwing warnt bei:</p><ul><li><strong>Überbuchung</strong> des Tankers,</li><li>Slots <strong>außerhalb des Orbit-Fensters</strong>,</li><li><strong>Boom oder Drogue</strong> passt nicht – die F-16 braucht einen Boom, die F/A-18 einen Drogue (die KC-135 MPRS z. B. nur Drogue).</li></ul><h2 id="prufungen-und-deconfliction" tabindex="-1">Prüfungen und Deconfliction <a class="header-anchor" href="#prufungen-und-deconfliction" aria-label="Permalink to &quot;Prüfungen und Deconfliction&quot;">​</a></h2><p><strong>Prüfungen</strong> listet Timing-Konflikte: zu früh, zu spät, lange Wartezeit, Push-Abweichung.</p><p><strong>Deconfliction</strong> sucht Stellen, an denen sich zwei Routen laut Planung zu nahe kommen:</p><ul><li><strong>Konflikt, wenn näher als</strong> … NM und … ft (Standard 3 NM / 1.000 ft).</li><li><strong>Zielgebiet-Radius</strong> – ein Kreis um jeden geplanten Zielpunkt. Treffen sich zwei Flights darin, wird das nicht gemeldet: Über dem Ziel gelten die Absprachen der Piloten. 0 = überall prüfen.</li><li><strong>Treffpunkte</strong> – am selben Planungspunkt mit mindestens 1.000 ft Höhenabstand ist kein Konflikt (Umkreis je nach Art, z. B. 5 NM am RV, 10 NM am Holding).</li><li>Anzeige für <strong>Paket</strong>, <strong>Gewählter</strong> Flight oder <strong>Alle</strong>. Konflikte zwischen Flights ohne Timing stehen nur als Zahl da („4 weitere“).</li><li>Einen Konflikt oder ein ganzes Paar kannst du <strong>für alle ausblenden</strong> – wird in der Planung gespeichert.</li></ul><h2 id="mission-abspielen" tabindex="-1">Mission abspielen <a class="header-anchor" href="#mission-abspielen" aria-label="Permalink to &quot;Mission abspielen&quot;">​</a></h2><p>Mit <strong>▶ Ablauf</strong> oben rechts über der Sync-Matrix erscheint die Karte über der Matrix, und alle Flights bewegen sich nach dem Timing: So sieht jeder, wo er bei TOT ist und wer neben ihm fliegt. Denselben Knopf findest du in der <a href="./uebersicht">Übersicht</a> unten auf der Karte.</p><ul><li><strong>▶ / ❚❚</strong> spielt ab und hält an, <strong>×10 / ×60 / ×300</strong> ist das Tempo (Sekunden Mission je Sekunde).</li><li>Den <strong>Regler</strong> kannst du ziehen. Die Marken darauf sind Starts, Push, TOT, On Station, Tanker-Slots und – rot – Annäherungen aus der Deconfliction. Ein Klick auf eine Marke springt dorthin, <strong>⏮ ⏭</strong> zum vorigen und nächsten Ereignis.</li><li>Die <strong>blaue Linie in der Sync-Matrix</strong> ist derselbe Zeitpunkt. Ziehst du sie in der Zeitachse, wandern die Flugzeuge auf der Karte mit.</li><li>Am Flugzeug stehen Callsign und Höhe, vor dem Start „am Boden“ (ab dem Anlassen), nach der Landung „gelandet“.</li><li>Tanker und AWACS fliegen ihren Racetrack bis Off Track. Ein Flight mit Vul-Fenster kreist an seinem Stationspunkt, bis das Fenster endet.</li><li>Als Designer blendest du mit <strong>Rot</strong> die gegnerischen KI-Flights ein. Piloten sehen nur das eigene Paket.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Gezeigt wird die Planung, nicht eine Simulation: Positionen kommen aus den Zeiten der Route. Endet eine Route am Ziel, verschwindet der Flight dort. Client-Flights ohne Timing und spät aktivierte KI erscheinen nicht.</p></div><h2 id="startzeit-der-mission" tabindex="-1">Startzeit der Mission <a class="header-anchor" href="#startzeit-der-mission" aria-label="Permalink to &quot;Startzeit der Mission&quot;">​</a></h2><p>Als Designer änderst du die Startzeit links unter dem Missionsnamen (<em>Start</em>); die Zeit aus dem Mission Editor steht in Klammern daneben. Sie wird beim Speichern in die .miz geschrieben. Alle Wegpunkt-Zeiten der Missionsroute zählen ab dem Start und wandern mit; H, Sollzeiten und die TOS der Cartridges bleiben, wo sie sind.</p>',31)])])}const p=n(a,[["render",l]]);export{c as __pageData,p as default};
